import{t as i,j as t,S as n,P as o}from"./index-CPkoE1ni.js";import{M as c}from"./markdown-BlEbztvV.js";const u=`## What we collect

When you submit an enquiry we store your name, your selected contact detail (phone, WhatsApp or email), your area of interest, and any message you choose to send. We also record the page and form you used so we can route your enquiry to the right team.

## Why we collect it

Your information is used for one purpose: to respond to your enquiry and provide the counseling, admissions, visa or training service you asked about. Cost planner estimates are stored so a counselor can discuss them with you — they are never shared publicly.

## What we never ask for

Our public forms never request bank account numbers, financial passwords, passport scans or identity documents. If any document is ever needed, it is requested privately by a named staff member through a secure channel.

## Marketing consent

Marketing messages are sent only if you explicitly opt in. Consent is optional, unchecked by default, and you may withdraw it at any time by contacting us.

## Reviews & feeds

Reviews displayed on this site are synced from public Google, Facebook and Trustpilot profiles with attribution and links to the original source.

## Your rights

You may request a copy, correction or deletion of your enquiry record at any time: email kishaainternational@gmail.com or call +971 58 682 6099 / +92 312 552 6099.

## Retention

Enquiry records are retained for the period needed to serve you and meet operational requirements, then anonymised or deleted according to our retention schedule.`,d=`## The service

Kishaa International provides career counseling, immigration consultancy and Cambridge / IELTS training from Dubai, UAE (Headquarters) and Pakistan.

## No guaranteed outcomes

Visa and admission decisions rest solely with the respective embassies, immigration authorities and universities. We provide transparent, professional preparation and never promise approvals.

## Fees

Advisory fees are always quoted separately from official embassy fees, university tuition and test fees. Where milestone payments are offered, the schedule is agreed in writing before work begins.

## Estimates

Cost planner figures are indicative planning estimates based on maintained statistical datasets and official rules with stated effective dates. Live flight fares are confirmed at consultation.

## Content

Guides and country intelligence are prepared with care but may change as official rules change. Always confirm the current rule with the relevant authority or with our team before acting.`;function l(e){if(!e)return null;try{const a=typeof e=="string"?JSON.parse(e):e;if(Array.isArray(a)){const r=a.find(s=>s.type==="richtext"&&s.html);if(r?.html)return r.html}}catch{}return null}function p(){const{data:e}=i.content.pages.bySlug.useQuery({slug:"privacy"}),a=l(e?.blocks);return t.jsxs(t.Fragment,{children:[t.jsx(n,{title:e?.seo_title||e?.title||"Privacy Policy",description:e?.seo_description||"How Kishaa International collects, uses and protects your enquiry data.",path:"/privacy"}),t.jsx(o,{eyebrow:"Legal",title:e?.title||"Privacy Policy"}),t.jsx("div",{className:"mx-auto max-w-3xl px-4 py-16 sm:px-6",children:a?t.jsx("div",{className:"prose prose-navy max-w-none text-[15px] leading-relaxed text-navy/80 space-y-4",dangerouslySetInnerHTML:{__html:a}}):t.jsx(c,{children:u})})]})}function h(){const{data:e}=i.content.pages.bySlug.useQuery({slug:"terms"}),a=l(e?.blocks);return t.jsxs(t.Fragment,{children:[t.jsx(n,{title:e?.seo_title||e?.title||"Terms of Service",description:e?.seo_description||"Terms of service for Kishaa International consultancy and training services.",path:"/terms"}),t.jsx(o,{eyebrow:"Legal",title:e?.title||"Terms of Service"}),t.jsx("div",{className:"mx-auto max-w-3xl px-4 py-16 sm:px-6",children:a?t.jsx("div",{className:"prose prose-navy max-w-none text-[15px] leading-relaxed text-navy/80 space-y-4",dangerouslySetInnerHTML:{__html:a}}):t.jsx(c,{children:d})})]})}export{p as Privacy,h as Terms};
